package in.tucor.api.buyer;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="buyer_bank_accounts") public class BuyerBankAccount{@Id public UUID id;@Column(name="buyer_id",nullable=false)public UUID buyerId;@Column(name="bank_name",nullable=false)public String bankName;@Column(name="account_type",nullable=false)public String accountType;@Column(name="account_holder_name",nullable=false)public String accountHolderName;@Column(name="account_number",nullable=false)public String accountNumber;@Column(nullable=false)public String ifsc;public String branch;public boolean verified;@Column(name="is_primary")public boolean primary;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="updated_at",nullable=false)public Instant updatedAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void update(){updatedAt=Instant.now();}}
